#!/usr/bin/env python3
"""Turn 35 Wave 90: THE PER-TIER POSITION BUILDS, AND A THREE-WAY VERSION-ATTRIBUTION CONFLICT.

Wave 90's centrepieces:

1. THE PER-TIER POSITION BUILDS, which the corpus did not have. The corpus carries "ideal
   blueprints" - the stat targets for a MAXED legendary player. What it lacked is the
   recruitment table you actually use: what to look for in a Common, a Rare and a Legendary at
   each position. A DLS24 positional guide gives the whole thing - CB, fullback, CM, DM, AM and
   second striker, each split by card tier - plus the reasoning for each stat.

2. CB PACE IS THE TOP CENTRE-BACK STAT, and the reason is mechanical rather than aesthetic:
   "you can't chase forwards with a slow CB. And it is the most recurring occasion in DLS where
   a CB chases a forward." That inverts the intuition that a centre-back is a strength-and-
   tackling position, and it changes who you buy.

3. A THREE-WAY VERSION-ATTRIBUTION CONFLICT on when "unlimited special players" arrived. The
   corpus currently carries three different answers - launch (13.040), Winter Reload, and
   Summer Spotlight - while the official App Store block puts it in **13.050, 15 January 2026**.
   Recorded as a conflict rather than silently picking one.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w90')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

e_pb=new_ev("r/DreamLeagueSoccer 1bxd927 'Guide to Various Positions in DLS24' (6 Apr 2024 - the complete per-tier positional builds for GK, CB, fullback, CM, DM, AM and second striker, with the stat reasoning and the named best players at each position), r/DreamLeagueSoccer 12bajfs 'What Stats should every position have?' (4 Apr 2023 - the concise per-position minimum targets), r/DreamLeagueSoccer zd03eo (5 Dec 2022 - the top-3 stats per position), gamedls.net 'How To Read Player Stats' (1 Aug 2025 - the stat-to-position mapping), the App Store DLS26 version history (OFFICIAL - the complete 13.050 through 13.430 release-note blocks with dates, which is what resolves the unlimited-specials attribution), APKMirror DLS26 release pages (13.340 Jun 22, 13.350 Jul 14, 13.410 Aug 20, 13.430 Sep 16), fifaworldcupnews.com DLS26 features (23 Jul 2026, DOWNGRADED - the May 2026 GK-AI improvement and the August 2026 slide-tackle and collision changes)",
    "THE PER-TIER POSITION BUILDS, THE CB-PACE FINDING, AND A THREE-WAY VERSION-ATTRIBUTION CONFLICT. (1) THE PER-TIER BUILDS, which the corpus did not have - it carried ideal blueprints for a MAXED legendary and not the recruitment table you actually use. **CENTRE BACK** - Common: 70+ speed and acceleration, 65+ strength and tackling · Rare: 75+ speed and acceleration, 70+ strength, 80+ tackling · Legendary: 80+ speed and acceleration, 80+ strength, 90+ tackling. **FULLBACK** - Common: 70+ speed and acceleration, 65+ tackling and control · Rare: 75+ speed and acceleration, 80+ tackling and control · Legendary: 80+ speed and acceleration, 85+ tackling and control. **CENTRE MIDFIELDER** - Common: control, passing, shooting 75+, tackling and strength 70+, speed and acceleration 65+ · Rare: 80+ / 75+ / 75+ · Legendary: 90+ / 80+ / 75+. **DEFENSIVE MIDFIELDER** - Common: 60+ speed and acceleration, 65+ strength and tackle, 60+ control and passing · Rare: 60+ speed and acceleration, 80+ strength and tackle, 70+ control and passing. **SECOND STRIKER** - Common: 65+ speed and acceleration, control, passing and shooting · Rare: 70+ / 75+ / 75+ / 75+ · Legendary: 80+ / 85+ / 85+ / 85+. (2) CB PACE IS THE TOP CENTRE-BACK STAT, and the reason is mechanical: '**Good pace is the most important stat for a CB, you can't chase forwards with a slow CB. And it is the most recurring occasion in DLS where a CB chases a forward.**' So the centre-back is a recovery position, not a static one, and a slow CB is a liability regardless of his tackling. (3) THE LOW-CB COUNTER: '**When facing long ball spammers, try to keep a low height fullback at CB to chase down forwards.**' A second, independent tactical answer to the long-ball problem, alongside the corpus's C-spam and wing-spam counters. (4) STRENGTH SLOWS FORWARDS: 'Strength plays an important role in not only tackles, but also **slowing forwards**. High strength defenders slow down forwards by putting pressure on them.' So STR is a containment stat as well as a collision one. (5) THE CONCISE TARGETS from a second thread: '**Any winger** should have at least 90+ in acc, speed, shooting, passing, control and stamina. If it's a **centre forward/false 9** then the same stats as a winger but ideally 95+ shooting. If it's a **striker** then 95+ speed and acceleration and shooting. 90+ control, strength and stamina. 88+ passing. A **CB** should have minimum 90+ tackling and pace. 95+ strength. 80+ passing and control.' (6) THE TOP-3 PER POSITION, from a third thread: '**Defenders** - 1) Strength, 2) Tackle, 3) Pass/Speed (same importance) · **Midfielders** - 1) Pass, 2) Speed, 3) Ball Control, 4) Shooting, 5) Strength · **Forwards** - 1) Speed, 2) Ball Control, 3) Shooting. Addition: **Tackle is an important stat for a DM**.' Note this ranks STR above TAC for defenders, where the per-tier table puts pace first - a genuine internal disagreement between two community sources, recorded rather than smoothed. (7) THE NAMED BESTS BY POSITION: CB - Van Dijk, Kim, Militão (Rúben Dias 'less preferred for his low height'); LB - Cancelo, Grimaldo; RB - Hakimi, Trent, Walker; CM - Valverde and Bellingham 'by far the best', then Modric, De Jong, Gündoğan, Çalhanoğlu, Kroos; DM - Rodri 'by far', then Casemiro, Guimarães, Rice; SS - Messi and Griezmann 'by far the best', with Mbappé as a support striker. (8) A THREE-WAY VERSION-ATTRIBUTION CONFLICT on when unlimited special players arrived. The corpus currently carries three answers: CLAIM-054 attributes it to the 13.040 launch (17 Dec 2025), CLAIM-202 to Summer Spotlight, and the App Store block the corpus itself quotes puts it in **13.050, 15 January 2026** - 'Increased squad size - Now with unlimited special players in your club.' The App Store block is the primary source and the most specific, so 13.050 is the leading answer, but the conflict is recorded rather than silently resolved. (9) THE EXACT VERSION DATES, from the official store and APKMirror together: 13.340 Jun 22 · 13.350 Jul 14 · 13.410 Aug 20 · 13.420 Sep 1 · 13.430 Sep 16, all 2026 - and all three of the 13.4x builds carry the same 'late summer update: Cult Heroes coming soon + bug fixes' notes, so the late-summer period was announcement-and-fixes rather than feature work. (10) THE MAY 2026 GAMEPLAY CHANGE, corroborating the corpus's GK finding: 'Refined ball physics and noticeable improvements to goalkeeper AI, specifically during 1-on-1 situations and corner kicks' - from a DOWNGRADED source, so recorded at C3 with the flag.",
    "THE PER-TIER POSITION BUILDS, which the corpus lacked because it only had blueprints for MAXED legends: CB Common 70+ pace/acc, 65+ STR/TAC, Rare 75+/70+/80+, Legendary 80+/80+/90+; fullback Common 70+ pace/acc, 65+ TAC/CON, Rare 75+/80+/80+, Legendary 80+/85+/85+; CM Common 75+ CON/PAS/SHO, 70+ TAC/STR, 65+ pace/acc, Rare 80+/75+/75+, Legendary 90+/80+/75+; DM Common 60+ pace/acc, 65+ STR/TAC, 60+ CON/PAS, Rare 60+/80+/70+; SS Common 65+, Rare 75+, Legendary 85+. CB PACE IS THE TOP CENTRE-BACK STAT because 'it is the most recurring occasion in DLS where a CB chases a forward' - so a slow CB is a liability regardless of tackling. THE LOW-CB COUNTER: against long-ball spammers, play a low fullback at CB to chase forwards down. STRENGTH SLOWS FORWARDS on pressure. NAMED BESTS: Van Dijk/Kim/Militão at CB (Dias avoided for height), Cancelo/Grimaldo LB, Hakimi/Trent/RB, Valverde/Bellingham CM, Rodri DM, Messi/Griezmann SS. A THREE-WAY VERSION-ATTRIBUTION CONFLICT on unlimited specials - launch vs Winter Reload vs Summer Spotlight vs the App Store's 13.050 (15 Jan 2026), which is the primary source and the leading answer.",
    "THE PER-TIER POSITION BUILDS, THE CB-PACE FINDING, AND A VERSION-ATTRIBUTION CONFLICT",
    quality="community")

add_claim("THE PER-TIER CENTRE-BACK BUILD, which the corpus lacked because it only carried blueprints for MAXED legends: **Common 70+ speed and acceleration, 65+ strength and tackling · Rare 75+ speed and acceleration, 70+ strength, 80+ tackling · Legendary 80+ speed and acceleration, 80+ strength, 90+ tackling.**", 3, "positions/cb-per-tier-build", [e_pb])
add_claim("CB PACE IS THE TOP CENTRE-BACK STAT, and the reason is mechanical rather than aesthetic: '**Good pace is the most important stat for a CB, you can't chase forwards with a slow CB. And it is the most recurring occasion in DLS where a CB chases a forward.**' So the centre-back is a recovery position, and a slow CB is a liability regardless of his tackling or strength.", 3, "positions/cb-pace-is-the-top-stat", [e_pb], notes="Inverts the intuition that a CB is a strength-and-tackling position")
add_claim("THE LOW-CB COUNTER TO LONG-BALL SPAM: '**When facing long ball spammers, try to keep a low height fullback at CB to chase down forwards.**' A second, independent tactical answer to the long-ball problem, alongside the corpus's C-spam and wing-spam counters - and it is a personnel answer, not a shape one.", 3, "tactics/low-cb-counter-to-long-ball-spam", [e_pb])
add_claim("STRENGTH SLOWS FORWARDS, not just wins collisions: 'Strength plays an important role in not only tackles, but also **slowing forwards**. High strength defenders slow down forwards by putting pressure on them.' So STR is a containment stat, which is why it outranks shooting on a defender's build.", 3, "attributes/strength-slows-forwards", [e_pb])
add_claim("THE PER-TIER FULLBACK BUILD: **Common 70+ speed and acceleration, 65+ tackling and control · Rare 75+ speed and acceleration, 80+ tackling and control · Legendary 80+ speed and acceleration, 85+ tackling and control.** Passing and shooting are 'good to have' for a fullback rather than primary.", 3, "positions/fullback-per-tier-build", [e_pb])
add_claim("THE PER-TIER CENTRE-MIDFIELDER BUILD: **Common - control, passing, shooting 75+, tackling and strength 70+, speed and acceleration 65+ · Rare - 80+ / 75+ / 75+ · Legendary - 90+ / 80+ / 75+.** So the CM weights control and passing first, then the physical pair, with pace last - and midfielders are 'all-rounders' who 'often act as backups for all positions.'", 3, "positions/cm-per-tier-build", [e_pb])
add_claim("THE PER-TIER DEFENSIVE-MIDFIELDER BUILD: **Common - 60+ speed and acceleration, 65+ strength and tackle, 60+ control and passing · Rare - 60+ speed and acceleration, 80+ strength and tackle, 70+ control and passing.** Height matters too, because DMs contest aerial duels in defending AND at corners. Shooting is optional but enhances long shots.", 3, "positions/dm-per-tier-build", [e_pb])
add_claim("THE PER-TIER SECOND-STRIKER BUILD: **Common - 65+ speed and acceleration, control, passing and shooting · Rare - 70+ / 75+ / 75+ / 75+ · Legendary - 80+ / 85+ / 85+ / 85+.** For a second striker, control and passing matter as much as shooting, because the role links play rather than finishing it.", 3, "positions/second-striker-per-tier-build", [e_pb])
add_claim("THE CONCISE PER-POSITION TARGETS, from a second independent thread: '**Any winger** should have at least **90+ in acc, speed, shooting, passing, control and stamina**. If it's a **centre forward/false 9** then the same stats as a winger but ideally **95+ shooting**. If it's a **striker** then **95+ speed and acceleration and shooting**, 90+ control, strength and stamina, 88+ passing. A **CB** should have minimum **90+ tackling and pace**, 95+ strength, 80+ passing and control.'", 3, "positions/concise-per-position-targets", [e_pb])
add_claim("THE TOP-3 STATS PER POSITION, from a third thread: '**Defenders** - 1) Strength, 2) Tackle, 3) Pass/Speed (same importance) · **Midfielders** - 1) Pass, 2) Speed, 3) Ball Control, 4) Shooting, 5) Strength · **Forwards** - 1) Speed, 2) Ball Control, 3) Shooting. Addition: **Tackle is an important stat for a DM.**' **Note the disagreement:** this ranks strength above tackling for defenders, where the per-tier table puts pace first - two community sources, two orderings, recorded rather than smoothed.", 3, "positions/top-3-per-position-ranking", [e_pb], notes="Records an internal disagreement between two community sources")
add_claim("THE NAMED BESTS BY POSITION: **CB** - Van Dijk, Kim, Militão (Rúben Dias 'less preferred for his low height') · **LB** - Cancelo, Grimaldo · **RB** - Hakimi, Trent, Walker · **CM** - Valverde and Bellingham 'by far the best', then Modric, De Jong, Gündoğan, Çalhanoğlu, Kroos · **DM** - Rodri 'by far', then Casemiro, Guimarães, Rice · **SS** - Messi and Griezmann 'by far the best', with Mbappé usable as a support striker.", 3, "positions/named-best-players", [e_pb])
add_claim("A THREE-WAY VERSION-ATTRIBUTION CONFLICT on when 'unlimited special players' arrived. The corpus currently carries three answers: CLAIM-054 attributes it to the **13.040 launch** (17 Dec 2025), CLAIM-202 to **Summer Spotlight**, and the App Store block the corpus itself quotes puts it in **13.050, 15 January 2026** - 'Increased squad size - Now with unlimited special players in your club.' **The App Store block is the primary source and the most specific, so 13.050 is the leading answer** - but the conflict is recorded rather than silently resolved.", 3, "errata/unlimited-specials-three-way-attribution-conflict", [e_pb], notes="Resolves the wave-84 attribution note in favour of 13.050, with the conflict preserved")
add_claim("THE EXACT LATE-SUMMER VERSION DATES, from the official store and APKMirror together: **13.340 Jun 22 · 13.350 Jul 14 · 13.410 Aug 20 · 13.420 Sep 1 · 13.430 Sep 16**, all 2026 - and all three of the 13.4x builds carry the same 'late summer update: Cult Heroes coming soon + bug fixes' notes. So the late-summer period was announcement-and-fixes rather than feature work, which is useful when dating a claim.", 3, "patching/late-summer-version-dates", [e_pb])
add_claim("THE MAY 2026 GAMEPLAY CHANGE, corroborating the corpus's GK finding from a second angle: 'Refined ball physics and noticeable **improvements to goalkeeper AI, specifically during 1-on-1 situations and corner kicks**.' From a DOWNGRADED source, so recorded at C3 with the flag - but it is consistent with CLAIM-0549 and explains why the December 'keepers are too silly in 1v1' complaint may already be stale.", 3, "patching/may-2026-gk-ai-improvement", [e_pb])

for p in ['EV-503_per_tier_builds.html','EV-503b_version_attribution.html']:
    with open(os.path.join(RAW_DIR,p),'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f'Added {cl_id-1-last_cl} claims (CLAIM-{last_cl+1:04d}..CLAIM-{cl_id-1:04d}) and 1 EV (EV-{last_ev+1:03d}). Totals: {n_cl} claims / {n_ev} EVs')
